"""Plugin pages and record schema tables checked against the plugins (RAD-97, RAD-135).

usage: plugin_docs.py [--update] SOURCE_DIR BUILD_DIR

1. docs/plugins/<page>.md: the block between
   "<!-- generated by tools/ci/plugin_docs.py: begin -->" and "... end -->"
   is the settings, presets, sensors and self-test items that the built
   plugin reports through `yantra-radio-host settings` and `selftest`
   (simulator.so as is; the SDR plugins' test builds with the fake module
   of RAD-92; pei.so against yantra-pei-sim). Without --update a
   difference fails; with --update the blocks are rewritten.
2. docs/TETRA_RECORDS.md: every schema the plugins report in
   `yantra-radio-host info` has a "### `<id>`" table whose rows are
   exactly its fields with the same group, type and unit (level: dBFS or
   dBm), each with a meaning and a source (message or measurement with
   its EN 300 392-2 clause). These tables are hand-written; only checked.
Exit 0 when everything matches, 1 on a difference, 2 on a usage error.
"""
import json
import os
import re
import subprocess
import sys
import tempfile

BEGIN = "<!-- generated by tools/ci/plugin_docs.py: begin -->"
END = "<!-- generated by tools/ci/plugin_docs.py: end -->"
SERIAL = "0000000000000000a1b2c3d4e5f60001"


def run(cmd, env=None):
    p = subprocess.run(cmd, capture_output=True, text=True, env=env, timeout=300)
    if p.returncode not in (0, 1):  # selftest exits 1 when an item fails
        raise RuntimeError(f"{' '.join(cmd)}: exit {p.returncode}: {p.stderr.strip()}")
    return p.stdout


def items(text, section):
    """The items of one section of `yantra-radio-host settings` output."""
    out, inside, cur = [], False, None
    for line in text.splitlines():
        if re.match(r"^[a-z_]+:( |$)", line):
            inside = line.rstrip() == section + ":"
            continue
        if not inside:
            continue
        if re.match(r"^  [a-z][a-z0-9_.]* ", line):
            cur = line[2:]
            out.append(cur)
        elif out and cur is not None:  # a value over several lines
            out[-1] += "\n" + line
    return out


ITEM = re.compile(r"^(\S+) \((\w+), ([^)]*)\)(?: = (.*?))?(?: flags: ([a-z_ ]+))? - ([^\n]*)$", re.S)


def setting_row(item):
    m = ITEM.match(item)
    if not m:
        raise RuntimeError(f"cannot parse: {item!r}")
    key, typ, group, value, flags, label = m.groups()
    value = (value or "").split("\n")[0]
    rng = re.search(r"\[([^\]]*)\]\s*$", value)
    unit = ""
    if typ in ("double", "int", "uint"):
        parts = re.sub(r"\[[^\]]*\]\s*$", "", value).split()
        if len(parts) >= 2:
            unit = parts[1]
    flags = ", ".join((flags or "").replace("read_only", "").split())
    return f"| `{key}` | {label} | {typ} | {group} | {unit} | {rng.group(1) if rng else ''} | {flags} |"


def block(settings_text, selftest_text, note):
    lines = [BEGIN, "", note, "", "Settings (RAD-40, RAD-41):", "",
             "| Key | Label | Type | Group | Unit | Range | Flags |", "|---|---|---|---|---|---|---|"]
    lines += [setting_row(i) for i in items(settings_text, "settings")]
    presets = items(settings_text, "presets")
    lines += ["", "Presets (RAD-43):", ""]
    if presets:
        lines += ["| Id | Label |", "|---|---|"]
        for p in presets:
            pid, _, label = p.partition(" - ")
            lines.append(f"| `{pid}` | {label} |")
    else:
        lines.append("none.")
    lines += ["", "Sensors (RAD-45):", "", "| Key | Label | Type | Group | Unit |", "|---|---|---|---|---|"]
    for s in items(settings_text, "sensors"):
        row = setting_row(s).split(" | ")
        lines.append(" | ".join(row[:5]) + " |")
    lines += ["", "Self-test items (RAD-46), with the result in the test set-up above:", "",
              "| Item | Result here |", "|---|---|"]
    for line in selftest_text.splitlines():
        m = re.match(r"^  (pass|warn|fail|skip) (\S+) - ([^:]*)", line)
        if m:
            lines.append(f"| `{m.group(2)}` {m.group(3).strip()} | {m.group(1)} |")
    lines += ["", END]
    return "\n".join(lines)


def host_pair(host, plugin, env, device=None):
    dev = ["--device", device] if device else []
    s = run([host, "settings", "--plugin", plugin, *dev], env)
    t = run([host, "selftest", "--plugin", plugin, *dev], env)
    return s, t


def pages(src, build):
    host = os.path.join(build, "bin", "yantra-radio-host")
    plugins = os.path.join(build, "bin", "plugins")
    tests = os.path.join(build, "tests", "plugins")
    base = {k: v for k, v in os.environ.items() if not k.startswith("YANTRA_")}
    fake = dict(base, YANTRA_FAKE_SOAPY=json.dumps({"devices": [{
        "serial": SERIAL, "scenario": os.path.join(src, "tests/fixtures/soapy/fake_two_cells.json"),
        "paced": False}]}))
    out = {}
    s, t = host_pair(host, os.path.join(plugins, "simulator.so"), base)
    out["simulator"] = block(s, t, "Generated from `simulator.so` without a floor plan.")
    s, t = host_pair(host, os.path.join(tests, "hackrf_fake.so"), fake)
    out["hackrf"] = block(s, t, "Generated from the test build `hackrf_fake.so` (the HackRF plugin with the "
                          "fake module of RAD-92 imitating a HackRF One; same code as `hackrf.so`).")
    s, t = host_pair(host, os.path.join(tests, "soapysdr_fake.so"), fake)
    out["soapysdr"] = block(s, t, "Generated from the test build `soapysdr_fake.so` with the fake module "
                            "(HackRF One profile). The `gain_<element>`, `antenna`, `agc`, `clock_source`, "
                            "`arg_<key>` and `sensor_<key>` entries come from the module of the device "
                            "opened, so another radio shows its own.")
    sim = os.path.join(build, "bin", "yantra-pei-sim")
    with tempfile.TemporaryDirectory() as d:
        link = os.path.join(d, "pei0")
        wrap = [sim, "--link", link, "--scenario", os.path.join(src, "tests/fixtures/pei/terminal_cells.json"), "--"]
        s = run([*wrap, host, "settings", "--plugin", os.path.join(plugins, "pei.so"), "--device", "pei:" + link],
                base)
        t = run([*wrap, host, "selftest", "--plugin", os.path.join(plugins, "pei.so"), "--device", "pei:" + link],
                base)
    out["pei"] = block(s, t, "Generated from `pei.so` against the simulated terminal `yantra-pei-sim` "
                       "(tests/fixtures/pei/terminal_cells.json).")
    return out


SCHEMA_HEAD = re.compile(r"^  ([a-z][a-z0-9_]*) v\d+ \w+, \d+ fields")
FIELD = re.compile(r"^    (\S+) (\w+) (\w+)(?: \[([^\]]*)\])?$")


def schemas(build, src):
    """{schema id: {field: (type, group, unit)}} over the plugins that are built."""
    host = os.path.join(build, "bin", "yantra-radio-host")
    found = {}
    for p in ("simulator.so", "hackrf.so", "soapysdr.so", "pei.so"):
        path = os.path.join(build, "bin", "plugins", p)
        if not os.path.exists(path):
            continue
        cur = None
        for line in run([host, "info", "--plugin", path]).splitlines():
            m = SCHEMA_HEAD.match(line)
            if m:
                cur = found.setdefault(m.group(1), {})
                continue
            m = FIELD.match(line)
            if m and cur is not None:
                cur[m.group(1)] = (m.group(2), m.group(3), m.group(4) or "")
            elif not line.startswith("    "):
                cur = None
    return found


def check_schema_doc(src, build):
    text = open(os.path.join(src, "docs/TETRA_RECORDS.md"), encoding="utf-8").read()
    problems = []
    for sid, fields in schemas(build, src).items():
        m = re.search(r"^### `" + re.escape(sid) + r"`\n(.*?)(?=^#|\Z)", text, re.S | re.M)
        if not m:
            problems.append(f"TETRA_RECORDS.md: no table for schema {sid}")
            continue
        rows = {}
        for line in m.group(1).splitlines():
            cells = [c.strip() for c in line.strip().strip("|").split("|")]
            if len(cells) >= 6 and cells[0].startswith("`"):
                rows[cells[0].strip("`")] = cells
        for name, (typ, group, unit) in fields.items():
            r = rows.get(name)
            if not r:
                problems.append(f"TETRA_RECORDS.md {sid}: field {name} missing")
                continue
            doc_unit = r[3]
            unit_ok = doc_unit == unit or (name == "level" and unit in ("dBFS", "dBm")
                                           and doc_unit in ("dBFS", "dBFS or dBm", "dBm"))
            if r[1] != group or r[2] != typ or not unit_ok:
                problems.append(f"TETRA_RECORDS.md {sid}.{name}: doc says {r[1]}/{r[2]}/{doc_unit}, "
                                f"plugin says {group}/{typ}/{unit}")
            if len(r) < 6 or not r[4] or not r[5]:
                problems.append(f"TETRA_RECORDS.md {sid}.{name}: meaning or source empty")
    return problems


def main():
    args = sys.argv[1:]
    update = "--update" in args
    args = [a for a in args if a != "--update"]
    if len(args) != 2:
        print(__doc__, file=sys.stderr)
        return 2
    src, build = args
    problems = check_schema_doc(src, build)
    for name, gen in pages(src, build).items():
        path = os.path.join(src, "docs", "plugins", name + ".md")
        text = open(path, encoding="utf-8").read() if os.path.exists(path) else ""
        m = re.search(re.escape(BEGIN) + r".*?" + re.escape(END), text, re.S)
        if not m:
            problems.append(f"{path}: no generated block")
            continue
        if m.group(0) != gen:
            if update:
                open(path, "w", encoding="utf-8").write(text[:m.start()] + gen + text[m.end():])
                print(f"plugin_docs: rewrote {path}")
            else:
                problems.append(f"{path}: generated block differs (run tools/ci/plugin_docs.py --update)")
    for p in problems:
        print("plugin_docs:", p)
    print(f"plugin_docs: {len(problems)} problems")
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
